# shellcheck shell=sh
# review: a walkthrough of what was built, for the human to go through with the agent.
# Everything here is computed from git and the item, nothing is generated by a model.
[ $# -eq 0 ] || usage_die "usage: $NAME review"
need_repo
current_item || die "not on an item branch (see: $CMD status)"
item_phase

base=$(cfg sdd.base main)
mb=$(git merge-base "$base" HEAD)
title=$(fm_get title "$IFILE")
echo "Review: $ID $ITYPE · $title   ($BRANCH → $base)"
echo "phase   $PHASE   ($WHY)"

ap=$(fm_get approved "$IFILE")
if [ "$(gate_level approved "$ITYPE")" = off ]; then
	:
elif [ -z "$ap" ]; then
	echo "plan    not approved"
elif approval_ok; then
	echo "plan    approved ${ap#* }, unchanged since"
else
	echo "plan    approved ${ap#* }, CHANGED since: re-approve or revert the plan"
fi

if check_passed_here "$ID"; then
	echo "check   ✓ passed for this exact code ($(sed -n 's/^at=//p' "$ST/checks/$ID"))"
elif [ -f "$ST/checks/$ID" ]; then
	echo "check   ✗ last result: $(sed -n 's/^result=//p' "$ST/checks/$ID"), or the code changed since; run: $CMD check"
else
	echo "check   never run; run: $CMD check"
fi

echo
echo "Commits"
git log --format='  %h %s' "$mb..HEAD"
echo
echo "Code changed (outside $SPECS/)"
git diff --stat=100 "$mb" -- . ":(exclude)$SPECS" | sed 's/^/ /'
git ls-files --others --exclude-standard | grep -v "^$SPECS/" | sed 's/^/  untracked: /'

# section <heading>: the body of one "## " section of the item, guidance removed. Built runs
# up to "## Review", so headings an agent adds inside Built stay part of it.
section() {
	H=$1 awk '
		/^## / && !(on && ENVIRON["H"] == "Built" && $0 !~ /^## Review/) { on = (substr($0, 4) == ENVIRON["H"]); next }
		on' "$IFILE" | uncomment
}

frs=$(plan_frs)
if [ -n "$frs" ]; then
	echo
	echo "Requirements → where they are named outside $SPECS/ (tests should name the FR they prove)"
	unnamed=
	for fr in $frs; do
		# --untracked: agents often leave new tests uncommitted until the human ships.
		hits=$(git grep --untracked -nwF "$fr" -- . ":(exclude)$SPECS" 2>/dev/null | cut -d: -f1,2 | head -n 5 | paste -sd ' ' -)
		[ -n "$hits" ] || unnamed=1
		printf '  %-10s %s\n' "$fr" "${hits:-✗ not named anywhere}"
	done
	[ -z "$unnamed" ] || echo "  (✗ is for your review only: ship does not check it)"
fi

echo
echo "Built (written by the agent)"
section "Built" | sed '/^[[:space:]]*$/d; s/^/  /'
notes=$(section "Review (optional)" | sed '/^[[:space:]]*$/d; s/^/  /')
[ -z "$notes" ] || printf '\nReview notes (yours)\n%s\n' "$notes"
echo
echo "next    go through it together; changes → note them under \"## Review\" and the agent continues ($CMD next)"
echo "        satisfied → $CMD ship"
